"use client";

import { motion, useAnimationControls, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";
import type { ReactNode } from "react";

export function MarqueePrimitive({ items }: { items: ReactNode[] }) {
  const reduceMotion = useReducedMotion();
  const controls = useAnimationControls();
  const [paused, setPaused] = useState(false);
  const row = items.map((item, index) => <span key={index}>{item}</span>);
  useEffect(() => {
    if (reduceMotion) { controls.set({ x: "0%" }); return; }
    if (paused) { controls.stop(); return; }
    void controls.start({ x: [null, "-50%"], transition: { duration: 8, ease: "linear", repeat: Infinity } });
  }, [controls, paused, reduceMotion]);
  return (
    <div
      onPointerEnter={() => setPaused(true)}
      onPointerLeave={() => setPaused(false)}
      onFocus={() => setPaused(true)}
      onBlur={() => setPaused(false)}
      style={{ overflow: "hidden" }}
    >
      <motion.div
        initial={{ x: "0%" }}
        animate={controls}
        style={{ display: "flex", width: "max-content", gap: 32 }}
      >
        <span style={{ display: "flex", gap: 32 }}>{row}</span>
        <span aria-hidden="true" style={{ display: "flex", gap: 32 }}>{row}</span>
      </motion.div>
    </div>
  );
}
